SELECT canonical_smiles, molecule_dictionary.chembl_id, standard_type, standard_relation, standard_value, standard_units FROM activities JOIN assays ON activities.assay_id = assays.assay_id JOIN molecule_dictionary ON activities.molregno = molecule_dictionary.molregno JOIN compound_structures ON molecule_dictionary.molregno = compound_structures.molregno WHERE assays.chembl_id = 'CHEMBL1054503' AND activities.standard_value IS NOT NULL AND activities.standard_relation = '=' ORDER BY canonical_smiles ASC, molecule_dictionary.chembl_id ASC, standard_type ASC, standard_relation ASC, standard_value ASC, standard_units ASC
